/** Domain tests use real SQL constraints/transactions, with no Redis/network or external model. */
class LocalLifeTest {
    @TempDir Path files;
    JdbcTemplate db;Transactions tx;ObjectMapper json;LocalAccounts accounts;LocalShops shops;LocalCoupons coupons;LocalMedia media;LocalCommunity community;LocalOperations ops;LocalAssistantTools agent;LocalLifeConfiguration config;
    @BeforeEach void setup(){
        var source=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE;LOCK_TIMEOUT=10000","sa","");
        new ResourceDatabasePopulator(List.of("V1__upgrade.sql","V2__customer_sessions_and_storefront.sql","V18__campus_local_life.sql").stream().map(s->new ClassPathResource("db/migration/"+s)).toArray(ClassPathResource[]::new)).execute(source);
        db=new JdbcTemplate(source);tx=new Transactions(new DataSourceTransactionManager(source));json=new ObjectMapper().findAndRegisterModules().disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);config=new LocalLifeConfiguration(true,false);accounts=new LocalAccounts(db,tx,json,config);shops=new LocalShops(db,tx,json,config,accounts);media=new LocalMedia(db,tx,json,config,accounts,files.toString());ReflectionTestUtils.setField(shops,"media",media);coupons=new LocalCoupons(db,tx,json,config,accounts,shops);community=new LocalCommunity(db,tx,json,config,accounts,shops,media);ops=new LocalOperations(db,tx,json,config,accounts);agent=new LocalAssistantTools(config,shops,coupons,ops,db,tx,json);
        for(int i=1;i<=4;i++)user(i);operator(3);operator(4);
        db.update("INSERT INTO ux_shop VALUES(1,'测试咖啡馆','安静明亮的校园咖啡馆，适合下午聊天。',1)");
        db.update("INSERT INTO ux_local_shop(shop_id,category,campus,area,address,latitude,longitude,avg_price_cents,hours_json,closed_dates_json,tags_json,photos_json,cover_path,status,updated_at) VALUES(1,'咖啡茶饮','主校区','大学路','校园东门',31.03,121.442,3000,'[]','[]','[\"安静\"]','[]','/local-assets/shop-1.svg','PUBLISHED',CURRENT_TIMESTAMP)");
    }
    void user(long id){db.update("INSERT INTO ux_account(id,username,display_name,password_hash,created_at) VALUES(?,?,?,'disabled',CURRENT_TIMESTAMP)",id,"sample_"+id,"用户"+id);}
    void operator(long id){db.update("INSERT INTO ux_local_profile(user_id,role,updated_at) VALUES(?,'OPERATOR',CURRENT_TIMESTAMP)",id);}
    @SuppressWarnings("unchecked") Map<String,Object> map(Object o){return (Map<String,Object>)o;}
    String template(int capacity){return map(coupons.saveTemplate(3,null,Map.ofEntries(Map.entry("shopId",1),Map.entry("title","测试满减券"),Map.entry("minimumCents",10000),Map.entry("discountCents",2000),Map.entry("capacity",capacity),Map.entry("claimFrom",Instant.now().minusSeconds(60).toString()),Map.entry("claimUntil",Instant.now().plusSeconds(3600).toString()),Map.entry("validFrom",Instant.now().minusSeconds(60).toString()),Map.entry("validUntil",Instant.now().plusSeconds(7200).toString()),Map.entry("terms","每人限一张，免费领取且不可叠加。"),Map.entry("state","PUBLISHED")))).get("id").toString();}
    Map<String,Object> coupon(long user,String template){String id=map(coupons.claim(user,template)).get("id").toString();return coupons.detail(user,id,true);}
    Map<String,Object> redeem(Map<String,Object> c,String key){return Map.of("shopId",1,"code",c.get("redeemCode"),"amountCents",12000,"requestKey",key);}
    List<Object> race(int count,java.util.function.IntFunction<Object> work)throws Exception{var pool=Executors.newFixedThreadPool(Math.min(count,16));try{var jobs=new ArrayList<Future<Object>>();for(int i=0;i<count;i++){int n=i;jobs.add(pool.submit(()->{try{return work.apply(n);}catch(Problem e){return e;}}));}var results=new ArrayList<>();for(var f:jobs)results.add(f.get(30,TimeUnit.SECONDS));return results;}finally{pool.shutdownNow();}}
    @Test void concurrentClaimsConserveInventoryAndDuplicateClaimReturnsOriginal()throws Exception{
        String t=template(20);for(int i=200;i<300;i++)user(i);var outcomes=race(100,n->coupons.claim(n+200,t));assertEquals(20,outcomes.stream().filter(Map.class::isInstance).count());assertEquals(80,outcomes.stream().filter(x->x instanceof Problem p&&p.code.equals("COUPON_SOLD_OUT")).count());assertEquals(0,db.queryForObject("SELECT remaining FROM ux_coupon_template WHERE id=?",Integer.class,t));assertEquals(20,db.queryForObject("SELECT COUNT(*) FROM ux_user_coupon WHERE template_id=?",Integer.class,t));
        String other=template(5);var duplicates=race(25,n->coupons.claim(1,other));assertEquals(1,duplicates.stream().map(x->map(x).get("id")).distinct().count());assertEquals(4,db.queryForObject("SELECT remaining FROM ux_coupon_template WHERE id=?",Integer.class,other));
    }
    @Test void redeemAndVoidRaceHasOneWinnerAndOriginalOperationCanBeRetried()throws Exception{
        String t=template(1);var c=coupon(1,t);String id=c.get("id").toString();var payment=redeem(c,"redeem-test-0001");var cancel=Map.<String,Object>of("reason","用户反馈后作废测试券","requestKey","void-test-0001");
        var outcomes=race(2,n->n==0?coupons.redeem(3,payment):coupons.voidCoupon(4,id,cancel));assertEquals(1,outcomes.stream().filter(Map.class::isInstance).count());
        String state=db.queryForObject("SELECT state FROM ux_user_coupon WHERE id=?",String.class,id);assertTrue(Set.of("USED","VOID").contains(state));
        Object retry=state.equals("USED")?coupons.redeem(3,payment):coupons.voidCoupon(4,id,cancel);assertEquals(json.valueToTree(outcomes.stream().filter(Map.class::isInstance).findFirst().orElseThrow()),json.valueToTree(retry));assertEquals(state.equals("USED")?1:0,db.queryForObject("SELECT COUNT(*) FROM ux_coupon_redemption WHERE coupon_id=?",Integer.class,id));assertEquals(0,db.queryForObject("SELECT remaining FROM ux_coupon_template WHERE id=?",Integer.class,t));
    }
    @Test void operationKeyCannotBeReusedWithDifferentAmount(){var c=coupon(1,template(2));var b=redeem(c,"repeat-operation-1");coupons.redeem(3,b);var changed=new HashMap<>(b);changed.put("amountCents",13000);assertEquals("LOCAL_KEY_CONFLICT",assertThrows(Problem.class,()->coupons.redeem(3,changed)).code);assertEquals(10000,json.valueToTree(coupons.redeem(3,b)).path("paidCents").asInt());}
    @Test void futureCouponCanBeVoidedButCannotBeRedeemedAndExpiredCouponIsRejected(){var c=coupon(1,template(2));db.update("UPDATE ux_user_coupon SET valid_from=? WHERE id=?",LocalData.at(Instant.now().plusSeconds(60)),c.get("id"));assertEquals("COUPON_NOT_USABLE",assertThrows(Problem.class,()->coupons.redeem(3,redeem(c,"future-redeem-1"))).code);coupons.voidCoupon(3,c.get("id").toString(),Map.of("requestKey","future-void-01","reason","尚未生效的优惠券作废"));var expired=coupon(2,template(2));db.update("UPDATE ux_user_coupon SET valid_until=? WHERE id=?",LocalData.at(Instant.now().minusSeconds(1)),expired.get("id"));assertEquals("EXPIRED",coupons.detail(2,expired.get("id").toString(),false).get("state"));assertThrows(Problem.class,()->coupons.redeem(3,redeem(expired,"expired-redeem")));assertThrows(Problem.class,()->coupons.voidCoupon(3,expired.get("id").toString(),Map.of("requestKey","expired-void-01","reason","不能作废已经过期的券")));}
    @Test void couponSnapshotsAndOwnershipAndFrozenRules(){String t=template(2);var c=coupon(1,t);assertThrows(Problem.class,()->coupons.detail(2,c.get("id").toString(),true));assertFalse(map(((List<?>)map(coupons.wallet(1)).get("items")).get(0)).containsKey("redeemCode"));coupons.templateState(3,t,Map.of("state","PAUSED","version",1));assertEquals(c.get("terms"),coupon(1,t).get("terms"));assertThrows(Problem.class,()->coupons.claim(2,t));assertThrows(Problem.class,()->coupons.preview(1,c.get("redeemCode").toString(),1));assertThrows(Problem.class,()->coupons.preview(3,c.get("redeemCode").toString(),2));}
    @Test void reviewUniquenessHiddenEditAndDeleteKeepRatingHonest(){var body=Map.<String,Object>of("body","这是一家安静舒适的咖啡馆，适合和同学聊天。","rating",5);var r=map(community.review(1,1,null,body));String id=r.get("id").toString();assertEquals(id,map(community.review(1,1,null,body)).get("id"));assertEquals("REVIEW_EXISTS",assertThrows(Problem.class,()->community.review(1,1,null,Map.of("body","同一家店的另一条评价不应重复创建。","rating",4))).code);assertEquals(5.0,shops.detail(1,null).get("rating"));community.moderate(3,id,Map.of("state","HIDDEN","reason","演示审核暂时隐藏这条评价","version",1));assertNull(shops.detail(1,null).get("rating"));assertThrows(Problem.class,()->community.detail(id,2L));var updated=map(community.review(1,1,id,Map.of("body","修改后的评价仍然需要保持原来的隐藏状态。","rating",4,"version",2)));assertEquals("HIDDEN",updated.get("state"));assertThrows(Problem.class,()->community.deleteReview(1,id,1));community.deleteReview(1,id,3);assertDoesNotThrow(()->community.review(1,1,null,body));}
    @Test void concurrentLikesAndSignsAreIdempotentAndCannotLikeOwnReview()throws Exception{String id=map(community.review(1,1,null,Map.of("body","这里的环境不错，适合校园周末慢慢逛。","rating",4))).get("id").toString();assertEquals("SELF_LIKE_FORBIDDEN",assertThrows(Problem.class,()->community.like(1,id,true)).code);race(15,n->community.like(2,id,true));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM ux_review_like WHERE review_id=?",Integer.class,id));race(15,n->community.sign(1));assertEquals(1,community.signs(1).get("total"));assertEquals(1,community.signs(1).get("streak"));}
    @Test void streakCrossesYearAndLeapDayWithoutCalendarReset(){assertEquals(3,LocalCommunity.streak(Set.of(LocalDate.parse("2025-12-30"),LocalDate.parse("2025-12-31"),LocalDate.parse("2026-01-01")),LocalDate.parse("2026-01-01")));assertEquals(3,LocalCommunity.streak(Set.of(LocalDate.parse("2024-02-28"),LocalDate.parse("2024-02-29"),LocalDate.parse("2024-03-01")),LocalDate.parse("2024-03-02")));}
    @Test void privateUploadsBecomePublicOnlyAfterPublicationAndHideRevokesOldUrl()throws Exception{var bytes=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(20,20,BufferedImage.TYPE_INT_RGB),"png",bytes);String mediaId=map(media.upload(1,"REVIEW",new MockMultipartFile("file","test.png","image/png",bytes.toByteArray()))).get("id").toString();assertThrows(Problem.class,()->media.read(mediaId,null,false));assertThrows(Problem.class,()->media.read(mediaId,2L,false));assertTrue(media.read(mediaId,1L,false).length>0);var r=map(community.review(1,1,null,Map.of("body","带有图片的体验分享，发布前图片不能公开查看。","rating",4,"mediaIds",List.of(mediaId))));assertTrue(media.read(mediaId,null,true).length>0);community.moderate(3,r.get("id").toString(),Map.of("version",1,"state","HIDDEN","reason","暂时隐藏，核对图片内容"));assertThrows(Problem.class,()->media.read(mediaId,null,false));assertTrue(media.read(mediaId,1L,false).length>0);assertThrows(Problem.class,()->media.upload(2,"REVIEW",new MockMultipartFile("file","fake.jpg","image/jpeg","not an image".getBytes())));}
    @Test void favoritesAndCheckinsBelongToAccountAndRepeatSafely(){shops.favorite(1,"SHOP",1,true);shops.favorite(1,"SHOP",1,true);assertEquals(1,((List<?>)map(shops.favorites(1)).get("items")).size());assertTrue(((List<?>)map(shops.favorites(2)).get("items")).isEmpty());Object a=community.checkin(1,1,Map.of("note","今天来过")),b=community.checkin(1,1,Map.of("note","重复提交"));assertEquals(map(a).get("id"),map(b).get("id"));assertThrows(Problem.class,()->community.deleteCheckin(2,map(a).get("id").toString()));}
    @Test void policyVersionsAndFeedbackRetryArePersistent(){var p=Map.<String,Object>of("title","优惠券使用规则","category","券","keywords","过期,期限","body","优惠券到达有效期截止时间后不可继续使用。","state","PUBLISHED");var old=map(ops.savePolicy(3,null,p));var next=new HashMap<>(p);next.put("version",1);next.put("body","优惠券过期后不能核销，需要重新查看其他优惠。接到的说明仅为规则。 ");ops.savePolicy(3,old.get("id").toString(),next);assertEquals(1,ops.policies("过期").size());assertEquals("ARCHIVED",db.queryForObject("SELECT state FROM ux_policy WHERE id=?",String.class,old.get("id")));var f=Map.<String,Object>of("requestKey","feedback-original-key","title","使用反馈","body","我在查看店铺信息时发现营业时间需要更新。");assertEquals(map(ops.feedback(1,f)).get("id"),map(ops.feedback(1,f)).get("id"));assertTrue(((List<?>)map(ops.myFeedback(2)).get("items")).isEmpty());}
    @Test void localAgentEnforcesFiltersReferencesAndIdentity(){var cp=new Checkpoint();var first=agent.execute("search_shops",json.valueToTree(Map.of("campus","主校区","maxPriceCents",2000)),1,cp);assertTrue(first.path("data").path("shops").isEmpty());assertEquals("ASSISTANT_CONSTRAINT_CHANGE",assertThrows(Problem.class,()->agent.execute("search_shops",json.createObjectNode().put("maxPriceCents",5000),1,cp)).code);assertThrows(Problem.class,()->agent.execute("get_my_coupons",json.createObjectNode().put("userId",2),1,cp));assertThrows(Problem.class,()->agent.execute("get_shop",json.createObjectNode().put("shopId","1"),1,cp));var next=new Checkpoint();next.state=cp.state;assertFalse(agent.execute("search_shops",json.createObjectNode().put("maxPriceCents",5000),1,next).path("data").path("shops").isEmpty());assertFalse(agent.execute("get_my_coupons",json.createObjectNode(),1,next).toString().contains("redeemCode"));}
    @Test void localFeatureGateRefusesCore32AndClosedFeatureReads(){assertThrows(IllegalStateException.class,()->new LocalLifeConfiguration(true,true).validate());assertThrows(Problem.class,()->new LocalLifeConfiguration(false,false).require());}
    @Test void recoveryCodeIsHashedSingleUseAndRevokesEverySession()throws Exception{
        var authentication=new Accounts(db,tx);String password="test-local-password-2026",next="replacement-password-2026";
        var hash=new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder(12).encode(password);db.update("UPDATE ux_account SET password_hash=? WHERE id=1",hash);
        var first=authentication.login("sample_1",password,"recovery-test");var second=authentication.login("sample_1",password,"recovery-test");String code=map(accounts.recoveryCode(1,password)).get("recoveryCode").toString();
        assertEquals(Accounts.digest(code),db.queryForObject("SELECT code_hash FROM ux_account_recovery WHERE user_id=1",String.class));assertNotEquals(code,db.queryForObject("SELECT code_hash FROM ux_account_recovery WHERE user_id=1",String.class));
        var outcomes=race(2,n->accounts.recover("sample_1",code,next,"recovery-"+n));assertEquals(1,outcomes.stream().filter(Map.class::isInstance).count());assertThrows(Problem.class,()->authentication.authenticate(first.cookie()));assertThrows(Problem.class,()->authentication.authenticate(second.cookie()));assertThrows(Problem.class,()->authentication.login("sample_1",password,"after-reset"));assertDoesNotThrow(()->authentication.login("sample_1",next,"after-reset"));
    }
    @Test void oldPasswordCheckCannotCreateSessionAfterConcurrentPasswordReset()throws Exception{
        String password="old-password-check-2026",next="reset-password-check-2026";var encoder=new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder(12);db.update("UPDATE ux_account SET password_hash=? WHERE id=1",encoder.encode(password));
        var blocked=new CountDownLatch(1);var release=new CountDownLatch(1);var spy=org.mockito.Mockito.spy(db);
        org.mockito.Mockito.doAnswer(invocation->{blocked.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return invocation.callRealMethod();}).when(spy).queryForObject(org.mockito.ArgumentMatchers.eq("SELECT id FROM ux_account WHERE id=? FOR UPDATE"),org.mockito.ArgumentMatchers.eq(Long.class),org.mockito.ArgumentMatchers.eq(1L));
        var authentication=new Accounts(spy,tx);var pool=Executors.newSingleThreadExecutor();try{var login=pool.submit(()->{try{return authentication.login("sample_1",password,"race");}catch(Problem failure){return failure;}});assertTrue(blocked.await(5,TimeUnit.SECONDS));accounts.changePassword(1,password,next);release.countDown();Object result=login.get(5,TimeUnit.SECONDS);assertInstanceOf(Problem.class,result);assertEquals("BAD_CREDENTIALS",((Problem)result).code);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM ux_session WHERE user_id=1",Integer.class));}finally{release.countDown();pool.shutdownNow();}
    }
    @Test void totalBudgetRequiresPeopleAndPerPersonCanReplaceItAcrossTurns(){
        var missing=new Checkpoint();assertEquals("LOCAL_PARTY_SIZE_REQUIRED",assertThrows(Problem.class,()->agent.execute("search_shops",json.createObjectNode().put("totalBudgetCents",6000),1,missing)).code);
        var cp=new Checkpoint();var first=agent.execute("search_shops",json.createObjectNode().put("totalBudgetCents",6000).put("people",3),1,cp);assertEquals("2000",cp.state.shopFilters.get("maxPriceCents"));assertEquals(0,first.path("data").path("shops").size());
        var next=new Checkpoint();next.state=cp.state;assertEquals(1,agent.execute("search_shops",json.createObjectNode().put("maxPriceCents",3500),1,next).path("data").path("shops").size());assertFalse(next.state.shopFilters.containsKey("totalBudgetCents"));
    }
    @Test void agentCannotCompareAnUnavailableCandidateOrInventUnsearchedShop(){
        var cp=new Checkpoint();agent.execute("search_shops",json.createObjectNode(),1,cp);assertThrows(Problem.class,()->agent.execute("get_shop",json.createObjectNode().put("position",2),1,cp));assertThrows(Problem.class,()->agent.execute("compare_shops",json.createObjectNode().set("positions",json.valueToTree(List.of(1,1))),1,cp));db.update("UPDATE ux_local_shop SET status='CLOSED' WHERE shop_id=1");assertThrows(Problem.class,()->agent.execute("get_shop",json.createObjectNode().put("position",1),1,cp));
    }
    @Test void agentCouponResultsReflectExpiryAndNeverContainCodes(){
        var coupon=coupon(1,template(1));db.update("UPDATE ux_user_coupon SET valid_until=? WHERE id=?",LocalData.at(Instant.now().minusSeconds(1)),coupon.get("id"));var cp=new Checkpoint();var result=agent.execute("get_my_coupons",json.createObjectNode(),1,cp);assertEquals("EXPIRED",result.path("data").path("items").get(0).path("state").asText());assertFalse(result.toString().contains(coupon.get("redeemCode").toString()));assertTrue(agent.execute("get_my_coupons",json.createObjectNode(),2,new Checkpoint()).path("data").path("items").isEmpty());
    }
    @Test void agentSupportIsOnlyADraftAndRejectsUnknownWriteTools(){
        var draft=agent.execute("prepare_support_draft",json.createObjectNode().put("title","需要协助").put("body","我想核对店铺的营业时间，请工作人员协助更新。"),1,new Checkpoint());assertFalse(draft.path("data").path("submitted").asBoolean());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM ux_feedback",Integer.class));assertEquals("ASSISTANT_TOOL_FORBIDDEN",assertThrows(Problem.class,()->agent.execute("claim_coupon",json.createObjectNode(),1,new Checkpoint())).code);assertThrows(Problem.class,()->agent.execute("prepare_support_draft",json.createObjectNode().put("title","不要保存密码").put("body","a".repeat(64)),1,new Checkpoint()));
    }
    @Test void agentMissingPolicyReturnsEmptyEvidenceInsteadOfInventedRule(){var result=agent.execute("search_policies",json.createObjectNode().put("q","不存在的退款规则"),1,new Checkpoint());assertTrue(result.path("data").path("items").isEmpty());assertTrue(result.path("sources").isEmpty());}
    @TestFactory List<DynamicTest> deterministicShopConstraintCases(){var tests=new ArrayList<DynamicTest>();for(String category:LocalShops.CATEGORIES)for(String campus:List.of("主校区","东校区","南校区"))for(int budget:List.of(0,2999,5000)){String label=category+" / "+campus+" / "+budget;tests.add(DynamicTest.dynamicTest(label,()->{var cp=new Checkpoint();var r=agent.execute("search_shops",json.valueToTree(Map.of("category",category,"campus",campus,"maxPriceCents",budget)),1,cp);boolean found=category.equals("咖啡茶饮")&&campus.equals("主校区")&&budget>=3000;assertEquals(found?1:0,r.path("data").path("shops").size());assertEquals(Integer.toString(budget),cp.state.shopFilters.get("maxPriceCents"));assertTrue(r.path("sources").size()>0);}));}
        for(String name:List.of("get_shop","compare_shops","get_my_coupons","get_my_payment_status","search_policies","prepare_support_draft"))tests.add(DynamicTest.dynamicTest("reject identity injection: "+name,()->assertThrows(Problem.class,()->agent.execute(name,json.createObjectNode().put("userId",2),1,new Checkpoint()))));return tests;
    }
}
